import React from "react";

function UserList({ users }) {
  const getRoleColor = (role) => {
    switch (role) {
      case "admin": return "text-red-600 font-semibold";
      case "editor": return "text-blue-600";
      case "viewer": return "text-gray-600";
      default: return "text-gray-500";
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case "admin": return "👑";
      case "editor": return "✏️";
      case "viewer": return "👁️";
      default: return "👤";
    }
  };

  const getRoleGradient = (role) => {
    switch (role) {
      case "admin": return "from-red-500 via-pink-500 to-rose-500";
      case "editor": return "from-blue-500 via-cyan-500 to-teal-500";
      case "viewer": return "from-gray-500 via-slate-500 to-zinc-500";
      default: return "from-gray-400 to-gray-500";
    }
  };

  return (
    <div className="w-80 bg-gradient-to-b from-gray-50 via-blue-50 to-indigo-50 border-l border-blue-200 p-8 shadow-2xl relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute inset-0 opacity-5">
        <div className="absolute top-10 right-10 w-24 h-24 bg-blue-300 rounded-full blur-2xl"></div>
        <div className="absolute bottom-20 left-10 w-32 h-32 bg-purple-300 rounded-full blur-2xl"></div>
      </div>
      
      <div className="relative z-10">
        <div className="mb-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-3 flex items-center">
            <span className="mr-3 text-3xl">👥</span>
            Connected Users
          </h2>
          <div className="bg-gradient-to-r from-blue-500 via-purple-500 to-indigo-500 text-white px-4 py-2 rounded-full text-sm font-bold inline-block shadow-lg">
            {users.length} {users.length === 1 ? 'user' : 'users'} online
          </div>
        </div>
        
        {users.length === 0 ? (
          <div className="text-center py-16">
            <div className="w-24 h-24 bg-gradient-to-br from-gray-200 to-gray-300 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
              <span className="text-5xl">👤</span>
            </div>
            <p className="text-gray-500 font-semibold text-lg">No users connected</p>
            <p className="text-gray-400 text-sm mt-2">Be the first to join!</p>
          </div>
        ) : (
          <div className="space-y-4">
            {users.map((user, index) => (
              <div key={user.id} className="group animate-fade-in" style={{ animationDelay: `${index * 100}ms` }}>
                <div className="bg-white/90 backdrop-blur-lg rounded-2xl p-5 shadow-xl border border-white/50 hover:shadow-2xl transition-all duration-300 hover:scale-105 hover:-translate-y-1">
                  <div className="flex items-center space-x-4">
                    <div className={`w-14 h-14 bg-gradient-to-br ${getRoleGradient(user.role)} rounded-2xl flex items-center justify-center shadow-xl transform group-hover:scale-110 transition-transform duration-300`}>
                      <span className="text-3xl">{getRoleIcon(user.role)}</span>
                    </div>
                    <div className="flex-1">
                      <div className="font-bold text-gray-900 group-hover:text-gray-700 transition-colors text-lg">
                        {user.username}
                      </div>
                      <div className={`text-sm ${getRoleColor(user.role)} flex items-center space-x-2 mt-1`}>
                        <span>{getRoleIcon(user.role)}</span>
                        <span className="capitalize font-medium">{user.role}</span>
                      </div>
                    </div>
                    <div className="flex flex-col items-end space-y-2">
                      <div className="relative">
                        <div className="w-4 h-4 bg-green-400 rounded-full animate-pulse shadow-lg"></div>
                        <div className="absolute inset-0 w-4 h-4 bg-green-400 rounded-full animate-ping opacity-75"></div>
                      </div>
                      <div className="text-xs text-green-600 font-semibold">Online</div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
        
        {/* Enhanced Role Legend */}
        <div className="mt-10 p-6 bg-white/80 backdrop-blur-lg rounded-2xl border border-white/50 shadow-xl">
          <h3 className="font-bold text-gray-800 mb-4 text-center text-lg">Role Permissions</h3>
          <div className="space-y-3 text-sm">
            <div className="flex items-center space-x-3 p-3 bg-gradient-to-r from-red-50 to-pink-50 rounded-xl border border-red-100 hover:shadow-md transition-shadow duration-200">
              <span className="text-2xl">👑</span>
              <div>
                <div className="font-bold text-red-800">Admin</div>
                <div className="text-red-600 text-xs">Full control + clear board</div>
              </div>
            </div>
            <div className="flex items-center space-x-3 p-3 bg-gradient-to-r from-blue-50 to-cyan-50 rounded-xl border border-blue-100 hover:shadow-md transition-shadow duration-200">
              <span className="text-2xl">✏️</span>
              <div>
                <div className="font-bold text-blue-800">Editor</div>
                <div className="text-blue-600 text-xs">Can draw and erase</div>
              </div>
            </div>
            <div className="flex items-center space-x-3 p-3 bg-gradient-to-r from-gray-50 to-slate-50 rounded-xl border border-gray-100 hover:shadow-md transition-shadow duration-200">
              <span className="text-2xl">👁️</span>
              <div>
                <div className="font-bold text-gray-800">Viewer</div>
                <div className="text-gray-600 text-xs">Read-only access</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default UserList;
